interface User {
  name: string;
  email: string;
  role: 'admin' | 'user' | 'guest';
}

/**
 * User class implementation
 */
class UserModel implements User {
  name: string;
  email: string;
  role: 'admin' | 'user' | 'guest';

  constructor(name: string, email: string, role: 'admin' | 'user' | 'guest' = 'user') {
    this.name = name;
    this.email = email;
    this.role = role;
  }

  /**
   * Get user's display info
   */
  getDisplayInfo(): string {
    return `${this.name} (${this.email}) - ${this.role}`;
  }

  /**
   * Check if user has admin privileges
   */
  isAdmin(): boolean {
    return this.role === 'admin';
  }

  /**
   * Update user's email
   */
  updateEmail(newEmail: string): void {
    this.email = newEmail;
  }

  /**
   * Convert to plain object
   */
  toJSON(): User {
    return {
      name: this.name,
      email: this.email,
      role: this.role,
    };
  }

  /**
   * Create UserModel from plain object
   */
  static fromJSON(data: User): UserModel {
    return new UserModel(data.name, data.email, data.role);
  }
}

export { User, UserModel };
