{"name":"write","arguments":{"path":"/root/.openclaw/workspace/timing_decorator.py","content":"import time
import functools
import logging

# Set up basic logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)


def timed(func=None, *, precision: int = 4):
    """
    Decorator that measures and logs function execution time.

    Can be used with or without arguments:
        @timed
        def my_func(): ...

        @timed(precision=2)
        def my_func(): ...

    Args:
        func: The function to decorate
        precision: Number of decimal places for timing output (default: 4)
    """
    def decorator(f):
        @functools.wraps(f)
        def wrapper(*args, **kwargs):
            start = time.perf_counter()
            result = f(*args, **kwargs)
            elapsed = time.perf_counter() - start
            logger.info(f"[{f.__name__}] executed in {elapsed:.{precision}f}s")
            return result
        return wrapper

    if func is not None:
        # Called without arguments: @timed
        return decorator(func)
    else:
        # Called with arguments: @timed(precision=2)
        return decorator


# Example usage
if __name__ == "__main__":
    @timed
    def quick_task():
        """Simulates a quick operation."""
        time.sleep(0.1)
        return "done"

    @timed(precision=2)
    def slow_task():
        """Simulates a slower operation."""
        time.sleep(0.5)
        return "finished"

    @timed
    def with_args(name, count=1):
        """Function with arguments."""
        time.sleep(0.05 * count)
        return f"Hello, {name}!"

    # Run examples
    print(quick_task())
    print(slow_task())
    print(with_args("World", count=2))
"}}
